/**
 * Single home for every asset path. Nothing in JSX should hardcode a path.
 *
 * The real photos are generated by `npm run memories` into
 * `public/images/memories/`. Illustrator output (if you commission any) goes
 * in the matching subfolders described in MASTER-PROMPT §10.
 */
export const assetPaths = {
  memories: "/images/memories",
  illustrations: "/images/illustrations",
  flowers: "/images/flowers",
  decorations: "/images/decorations",
  letters: "/images/letters",
  audio: "/audio",
} as const;

export const memorySrc = (id: string) => `${assetPaths.memories}/${id}.webp`;

/** The one audio track this project would play, if the owner ever adds one. */
export const musicTrack = {
  src: `${assetPaths.audio}/our-song.mp3`,
  title: "[TÊN BÀI HÁT]",
  artist: "[CA SĨ]",
};
